          trAutoOCR: "\u0410\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0440\u0435\u0436\u0438\u043C OCR",
          trSaveGlossary: "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0433\u043B\u043E\u0441\u0441\u0430\u0440\u0438\u0439",
          trDisableGlossary: "\u041E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0438\u0437\u0432\u043B\u0435\u0447\u0435\u043D\u0438\u0435 \u0433\u043B\u043E\u0441\u0441\u0430\u0440\u0438\u044F",
