    const buildDropdown = (id, options, defaultValue) => {
      const dd = createElement(doc, "div", "llm-tr-dropdown", {
        id
      });
      const trigger = createElement(
        doc,
        "div",
        "llm-tr-dropdown-trigger"
      );
      const arrow = createElement(
        doc,
        "span",
        "llm-tr-dropdown-arrow"
      );
      arrow.textContent = "\u25BE";
      trigger.textContent = "\u2014";
      trigger.appendChild(arrow);
      const menu = createElement(
        doc,
        "div",
        "llm-tr-dropdown-menu"
      );
      menu.style.display = "none";
      dd.append(trigger, menu);
      const selectItem = (value, label) => {
        dd.dataset.value = value;
        const arrowEl = trigger.querySelector(".llm-tr-dropdown-arrow");
        trigger.textContent = label;
        if (arrowEl) trigger.appendChild(arrowEl);
        menu.querySelectorAll(".llm-tr-dropdown-item").forEach((el) => {
          el.classList.toggle(
            "selected",
            el.dataset.value === value
          );
        });
        menu.style.display = "none";
        dd.classList.remove("open");
      };
      for (const opt of options) {
        const item2 = createElement(
          doc,
          "div",
          "llm-tr-dropdown-item"
        );
        item2.dataset.value = opt.value;
        item2.textContent = opt.label;
        item2.addEventListener("click", () => selectItem(opt.value, opt.label));
        menu.appendChild(item2);
      }
      const defaultOpt = options.find((o) => o.value === defaultValue) || options[0];
      if (defaultOpt) selectItem(defaultOpt.value, defaultOpt.label);
      trigger.addEventListener("click", () => {
        const open2 = menu.style.display !== "none";
        menu.style.display = open2 ? "none" : "block";
        dd.classList.toggle("open", !open2);
      });
      doc.addEventListener("click", (e) => {
        if (!dd.contains(e.target)) {
          menu.style.display = "none";
          dd.classList.remove("open");
        }
      });
      return dd;
    };
