    const clampFontInspectorPosition = (inspector, left, top) => {
      const margin = 12;
      const viewportWidth = win.innerWidth || doc.documentElement?.clientWidth || margin * 2;
      const viewportHeight = win.innerHeight || doc.documentElement?.clientHeight || margin * 2;
      const rect = inspector.getBoundingClientRect();
      const maxLeft = Math.max(margin, viewportWidth - rect.width - margin);
      const maxTop = Math.max(margin, viewportHeight - rect.height - margin);
      return {
        left: Math.min(maxLeft, Math.max(margin, left)),
        top: Math.min(maxTop, Math.max(margin, top))
      };
    };
    const positionFontInspectorAtCenter = (inspector) => {
      win.requestAnimationFrame(() => {
        const viewportWidth = win.innerWidth || doc.documentElement?.clientWidth || 0;
        const viewportHeight = win.innerHeight || doc.documentElement?.clientHeight || 0;
        const rect = inspector.getBoundingClientRect();
        const next = clampFontInspectorPosition(
          inspector,
          viewportWidth / 2 - rect.width / 2,
          viewportHeight / 2 - rect.height / 2
        );
        inspector.style.left = `${next.left}px`;
        inspector.style.top = `${next.top}px`;
        inspector.style.right = "auto";
        inspector.style.transform = "none";
      });
    };
    const makeFontInspectorDraggable = (inspector, handle) => {
      let dragOffsetX = 0;
      let dragOffsetY = 0;
      let dragging = false;
      const stopDrag = () => {
        if (!dragging) return;
        dragging = false;
        inspector.classList.remove("is-dragging");
        win.removeEventListener("mousemove", onMove);
        win.removeEventListener("mouseup", onUp);
      };
      const onMove = (event) => {
        if (!dragging) return;
        event.preventDefault();
        const next = clampFontInspectorPosition(
          inspector,
          event.clientX - dragOffsetX,
          event.clientY - dragOffsetY
        );
        inspector.style.left = `${next.left}px`;
        inspector.style.top = `${next.top}px`;
        inspector.style.right = "auto";
        inspector.style.transform = "none";
      };
      const onUp = () => {
        stopDrag();
      };
      const onDown = (event) => {
        if (event.button !== 0) return;
        const target = event.target;
        if (target?.closest?.("button,input,select,textarea,a")) return;
        const rect = inspector.getBoundingClientRect();
        dragOffsetX = event.clientX - rect.left;
        dragOffsetY = event.clientY - rect.top;
        inspector.style.left = `${rect.left}px`;
        inspector.style.top = `${rect.top}px`;
        inspector.style.right = "auto";
        inspector.style.transform = "none";
        dragging = true;
        inspector.classList.add("is-dragging");
        event.preventDefault();
        win.addEventListener("mousemove", onMove);
        win.addEventListener("mouseup", onUp);
      };
      handle.addEventListener("mousedown", onDown);
      return () => {
        handle.removeEventListener("mousedown", onDown);
        stopDrag();
      };
    };
