          selectionTranslateEnableHint: "\uC0AC\uC6A9\uD558\uBA74 Zotero \uB9AC\uB354\uC758 \uC120\uD0DD \uD31D\uC5C5\uC5D0\uC11C \uC120\uD0DD\uD55C \uD14D\uC2A4\uD2B8\uB97C \uBC88\uC5ED\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
          selectionTranslateAuto: "\uC120\uD0DD \uD6C4 \uC790\uB3D9 \uBC88\uC5ED",
          selectionTranslateAutoHint: "\uAEBC\uB3C4 \uC120\uD0DD \uD31D\uC5C5\uC5D0\uC11C \uC218\uB3D9\uC73C\uB85C \uBC88\uC5ED\uC744 \uC2DC\uC791\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
